mapper.select:
SELECT r.id, r.project_id, r.task_id, r.trigger_type, r.test_case_id, r.test_case_name,
       r.test_type, r.command_text, r.script_filename, r.script_content, r.script_hash,
       r.status, r.exit_code, r.summary, r.output, r.queued_at, r.started_at,
       r.finished_at, r.created_at
FROM test_case_run r
JOIN project p ON p.id = r.project_id
WHERE r.id = #{id}
  AND (
      p.owner_id = #{ownerId}
      OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
      )
  )

SELECT 
FROM test_case_run
WHERE test_case_id = #{testCaseId}
ORDER BY id DESC
LIMIT #{limit}

SELECT FROM ( SELECT r.*, ROW_NUMBER() OVER (PARTITION BY r.test_case_id ORDER BY r.id DESC) AS row_no FROM test_case_run r WHERE r.test_case_id IN
#{testCaseId}
) ranked WHERE ranked.row_no = 1

SELECT COUNT(*)
FROM test_case_run
WHERE task_id = #{taskId}

mapper.insert:
INSERT INTO test_case_run (
    project_id, task_id, trigger_type, test_case_id, test_case_name, test_type, command_text,
    script_filename, script_content, script_hash, status, exit_code, summary, output,
    queued_at, started_at, finished_at, created_at
) VALUES (
    #{projectId}, #{taskId}, #{triggerType}, #{testCaseId}, #{testCaseName}, #{testType}, #{commandText},
    #{scriptFilename}, #{scriptContent}, #{scriptHash}, #{status}, #{exitCode}, #{summary}, #{output},
    #{queuedAt}, #{startedAt}, #{finishedAt}, #{createdAt}
)
